parameters.jsCode:
const inputData = $input.item.json || {};
const textoSalida = valor => {
  if (valor === null || valor === undefined) return '';
  if (typeof valor === 'string' || typeof valor === 'number' || typeof valor === 'boolean') {
    return valor.toString();
  }
  if (Array.isArray(valor)) {
    return valor.map(textoSalida).filter(Boolean).join('\n');
  }
  if (typeof valor === 'object') {
    return textoSalida(valor.output || valor.text || valor.response || valor.result || valor.answer || valor.content || valor.message);
  }
  return '';
};
const extraerSalidaAgente = data => {
  const candidatos = [
    data.output,
    data.text,
    data.response,
    data.result,
    data.answer,
    data.message?.content,
    data.chatMessage?.content,
    data.generations?.[0]?.[0]?.text
  ];
  return candidatos.map(textoSalida).find(valor => valor.trim() !== '')?.trim() || '';
};
const output = extraerSalidaAgente(inputData);
const jsonMatch = output.match(/\{[\s\S]*?"accion"[\s\S]*?\}/);

// Toda la configuracion viene de Supabase (tablas clinicas + tratamientos).
const CFG = $('Construir contexto').first().json.config;
const TIME_ZONE = CFG.zona_horaria;
const DURACION_CITA_MIN = CFG.duracion_por_defecto;
const DURACIONES_TRATAMIENTO = CFG.duraciones;

const trigger = $('WhatsApp Trigger').first().json;
const telefono = trigger.messages?.[0]?.from || '';
const mensajeActual = trigger.messages?.[0]?.text?.body || '';

const normalizarTexto = texto => (texto || '')
  .toString()
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const datoVacio = valor => valor === null || valor === undefined || valor.toString().trim() === '';

const duracionTratamiento = tratamiento => {
  const valor = normalizarTexto(tratamiento);
  const encontrado = DURACIONES_TRATAMIENTO.find(item =>
    item.patrones.some(patron => valor.includes(normalizarTexto(patron)))
  );
  return encontrado ? encontrado.minutos : DURACION_CITA_MIN;
};


const mensajeActualNormalizado = normalizarTexto(mensajeActual);
const contieneTratamiento = texto => {
  const valor = normalizarTexto(texto);
  return DURACIONES_TRATAMIENTO.some(item =>
    item.patrones.some(patron => valor.includes(normalizarTexto(patron)))
  );
};
const esConsultaExplicitaHorarios = texto => /\b(horarios?|disponibilidad|disponibles?|huecos?|libres?|que horas|horas hay|agenda)\b/.test(normalizarTexto(texto));
const esRespuestaCortaTratamiento = texto => {
  const limpio = normalizarTexto(texto)
    .replace(/^(?:(?:para|por|de|del|una|un|la|el)\s+)+/, '')
    .trim();
  const palabras = limpio.split(/\s+/).filter(Boolean);
  return palabras.length > 0
    && palabras.length <= 5
    && contieneTratamiento(limpio)
    && !esConsultaExplicitaHorarios(limpio)
    && !/\b(cancelar|cambiar|modificar|mover|reprogramar|precio|cuanto|cuesta|coste)\b/.test(limpio);
};

const esMensajeSeleccionHora = texto => {
  const limpio = normalizarTexto(texto);
  return /(?:^|\b)(?:a\s*)?(?:las?|los)?\s*\d{1,2}(?::\d{2})?\s*(?:am|pm)?(?:\b|$)/.test(limpio)
    && !contieneTratamiento(limpio)
    && !esConsultaExplicitaHorarios(limpio)
    && !/\b(me llamo|soy|nombre|cancelar|cambiar|modificar|mover|reprogramar)\b/.test(limpio);
};

const nombrePareceEjemploPrompt = nombre => {
  const valor = normalizarTexto(nombre);
  return ['x', 'xx', 'xxx', 'nombre'].includes(valor)
    || valor.includes('nombre real')
    || valor.includes('nombre en memoria')
    || valor.includes('nombre del cliente')
    || valor.includes('nombre del paciente')
    || valor.includes('nombre_de_paciente')
    || valor.includes('nombre_del_paciente')
    || valor.includes('tu nombre completo')
    || valor.includes('[')
    || valor.includes(']');
};
const tratamientoGenerico = tratamiento => {
  const valor = normalizarTexto(tratamiento);
  return valor === 'cita' || valor.startsWith('cita est');
};
const tratamientoPareceEjemploPrompt = tratamiento => {
  const valor = normalizarTexto(tratamiento);
  return valor.includes('tratamiento real')
    || valor.includes('tratamiento en memoria')
    || valor.includes('[')
    || valor.includes(']');
};

const responder = texto => [{
  json: {
    accion: 'responder',
    es_reserva: false,
    es_cancelacion: false,
    es_modificacion: false,
    telefono,
    respuesta: texto
  }
}];

const esSaludoSimple = texto => /^(hola|buenas|buenos dias|buenas tardes|buenas noches|hey|hi|hello|ola|oi|bonjour|bonsoir|kaixo|epa)\b/.test(texto);
const preguntaIdentidad = texto => /\b(sabes quien soy|sabes quien soy\?|quien soy|me conoces|sabes mi nombre)\b/.test(texto);

const limitarTexto = (texto, max = 900) => {
  const valor = (texto || '').toString().replace(/\s+/g, ' ').trim();
  if (valor.length <= max) return valor;
  return valor.slice(0, max - 3).trim() + '...';
};

// ------------------------------------------------------------------ ambito
// Un modelo de lenguaje, si se le pide, escribe HTML, resuelve sumas o se
// disculpa en ingles. Todo eso llegaba al paciente tal cual porque la ultima
// linea de este nodo enviaba el texto del modelo sin mirarlo (se vio en
// pruebas reales: "20+50?" -> "70", "pasame el html" -> una pagina entera).
// Estas dos barreras NO dependen de que el modelo obedezca al prompt.
const RESPUESTAS_FUERA_DE_AMBITO = [
  'Perdona, con eso no puedo ayudarte: solo llevo las citas y la información de ' + CFG.nombre + '. ¿Te busco hueco para una cita?',
  'Uy, eso se me escapa. Yo solo me ocupo de las citas y de las dudas de la clínica. ¿Te ayudo con alguna?',
  'De eso no puedo ocuparme, lo siento. Donde sí te echo una mano es con tu cita o con cualquier duda de la clínica.'
];
// Se elige por el texto del mensaje, no al azar: la misma pregunta da siempre
// la misma respuesta (pruebas repetibles) pero dos mensajes distintos no
// sueltan la misma frase hecha, que es lo que delata a un bot.
const varianteSegun = (texto, opciones) => {
  const base = (texto || '').toString();
  let suma = 7;
  for (let i = 0; i < base.length; i++) suma = (suma * 31 + base.charCodeAt(i)) % 99991;
  return opciones[suma % opciones.length];
};

const pareceOperacionMatematica = texto => {
  const valor = normalizarTexto(texto).replace(/\s+/g, '');
  if (!valor) return false;
  if (/\d{1,2}[\/.\-]\d{1,2}/.test(valor)) return false;   // fechas
  if (/\d{1,2}:\d{2}/.test(valor)) return false;            // horas
  return /^\(?\d+\)?([+*x×÷\/^%]\(?\d+\)?)+[=?]*$/.test(valor);
};
const PATRONES_FUERA_DE_AMBITO = [
  /\b(hazme|hazle|haceme|escribeme|escribe|crea|crear|creame|genera|generame|programa|programame|disena|disename|pasame|dame)\b[^.?!]{0,40}\b(pagina web|paginas web|web|html|css|codigo|script|programa|app|aplicacion|python|javascript|sql|excel|macro|logo|cartel)\b/,
  /\b(html|css|javascript|python|codigo fuente|source code)\b/,
  /\b(traduce|traduceme|traducir|redacta|redactame|resumeme|corrigeme)\b/,
  /\b(receta|poema|poesia|cuento|chiste|cancion|ensayo|redaccion|curriculum|carta de presentacion|trabajo de clase|deberes)\b/,
  /\b(cuanto es|cuanto son|calcula|calculame|resuelve|resuelveme)\b[^.?!]{0,30}\d/,
  /\b(quien gano|quien es el presidente|quien invento|capital de|que tiempo (hace|va a hacer))\b/
];
const pareceFueraDeAmbito = texto => {
  const valor = normalizarTexto(texto);
  if (!valor) return false;
  // Si habla de la clinica, manda la clinica: nada de esto se aplica.
  if (contieneTratamiento(valor)) return false;
  if (/\b(cita|citas|reserva|reservar|reservo|cancelar|anular|modificar|cambiar|horario|horarios|hueco|huecos|precio|precios|presupuesto|clinica|dentista|dental|diente|dientes|muela|muelas|boca|encia|encias|factura|seguro)\b/.test(valor)) return false;
  if (pareceOperacionMatematica(valor)) return true;
  return PATRONES_FUERA_DE_AMBITO.some(patron => patron.test(valor));
};

// El cliente puede escribir en ingles y entonces el ingles es correcto. Solo se
// corrige la negativa en ingles cuando el cliente NO ha escrito en ingles.
const mensajePareceIngles = texto => /\b(hello|hi|good (morning|afternoon|evening)|i want|i need|i would|can i|could you|appointment|please|thanks|thank you|my name is|what time|do you have)\b/.test(normalizarTexto(texto));
const pareceNegativaEnIngles = texto => /\b(i'm sorry|i am sorry|sorry, but|i can't|i cannot|i can not|i'm unable|i am unable|as an ai|i'm not able|i am not able)\b/.test(normalizarTexto(texto));
const pareceCodigo = texto => /```|<!doctype|<html|<\/(div|p|body|head|html|style|script|h1|ul|li)>|<(div|span|body|head|script|style|h1)\b|function\s*\(|=>\s*\{/i.test((texto || '').toString());
const limpiarFormato = texto => (texto || '').toString()
  .replace(/```[\s\S]*?```/g, ' ')
  .replace(/^#{1,6}\s*/gm, '')
  .replace(/\*\*(.+?)\*\*/g, '$1')
  .replace(/\s+/g, ' ')
  .trim();

// Ultimo filtro antes de que el texto del modelo salga hacia WhatsApp.
const respuestaSegura = texto => {
  const limpio = limpiarFormato(texto);
  const mal = !limpio
    || pareceCodigo(texto)
    || (!mensajePareceIngles(mensajeActual) && pareceNegativaEnIngles(limpio));
  if (mal) return varianteSegun(mensajeActual, RESPUESTAS_FUERA_DE_AMBITO);
  return limitarTexto(limpio);
};


const limpiarNombreExtraido = valor => {
  const inicial = limitarTexto(valor, 160)
    .replace(/\s+/g, ' ')
    .replace(/^[,.;:!?\s]+|[,.;:!?\s]+$/g, '')
    .trim();
  const cortado = inicial
    .split(/\s+\b(?:porque|por que|no se|tengo|me duele|me sangra|sangra|ademas|cuando)\b/i)[0]
    .replace(/^[,.;:!?\s]+|[,.;:!?\s]+$/g, '')
    .trim();
  const palabras = cortado.split(/\s+/).filter(Boolean);
  if (palabras.length < 2 || palabras.length > 6) return '';
  if (/\d|\b(cita|revision|limpieza|blanqueamiento|empaste|ortodoncia|dolor|sangrado|muela|diente)\b/i.test(cortado)) return '';
  return nombrePareceEjemploPrompt(cortado) ? '' : cortado;
};

const extraerNombreMensaje = texto => {
  const raw = (texto || '').toString().replace(/\s+/g, ' ').trim();
  if (!raw) return '';
  const patrones = [
    /\b(?:a|al|en)\s+nombre\s+de\s+(.+?)(?=[,.;:!?]|$)/i,
    /\bnombre\s*[:=]\s*(.+?)(?=[,.;:!?]|$)/i,
    /\bme\s+llamo\s+(.+?)(?=[,.;:!?]|$)/i,
    /\bsoy\s+(.+?)(?=[,.;:!?]|$)/i
  ];
  for (const patron of patrones) {
    const match = raw.match(patron);
    const nombre = match ? limpiarNombreExtraido(match[1]) : '';
    if (nombre) return nombre;
  }
  return '';
};

// DETECTOR DE INFORMACION CLINICA (reescrito 15-sep-2026)
// Antes comparaba subcadenas: "Dolores", "Salvador", "febrero", "despues",
// "me puse" o "tomo nota" disparaban una derivacion falsa y callaban el bot
// 3 horas. Ahora cada termino es una expresion con limite de palabra (\b), los
// terminos cortos y ambiguos solo cuentan acompanados (pus, dor, golpe...), y
// "caries" sola ya no deriva: "quiero cita para mirarme una caries" es una
// peticion de cita normal en una clinica dental.
const PATRONES_CLINICOS = [
  // Espanol: dolor y molestias
  /\bduele(n)?\b/, /\bdolor(es)?\b/, /\bdolorid[oa]s?\b/, /\bmolestias?\b/,
  /\bsensibilidad\b/, /\bpunzadas?\b/, /\bpinchazos?\b/, /\bardor\b/,
  // Espanol: sangrado, infeccion, inflamacion
  /\bsangr(a|an|e|ado|ados|ando)\b/, /\bhemorragia\b/,
  /\b(sale|salen|tengo|tiene|con|echa|echando|saliendo)\s+pus\b/, /\bsupura(n|ndo)?\b/,
  /\babscesos?\b/, /\bflemon(es)?\b/, /\binfecci(on|ones)\b/, /\binfectad[oa]s?\b/,
  /\binflamad[oa]s?\b/, /\binflamacion\b/, /\bhinchad[oa]s?\b/, /\bhinchazon\b/,
  /\bbultos?\b/, /\bllagas?\b/, /\bheridas?\b/, /\bulceras?\b/, /\baftas?\b/, /\bfiebre\b/,
  // Espanol: roturas y golpes, solo si afectan a la boca
  /\b(diente|dientes|muela|muelas|paleta|colmillo|empaste|corona|funda|implante)\s+(roto|rota|rotos|rotas|partido|partida|suelto|suelta|movido|movida)\b/,
  /\bse me (ha |han )?(roto|rompio|partido|partio|caido|cayo|salido|salio|movido|soltado|solto|despegado|despego)\s+(un |una |el |la |los |las )?(diente|dientes|muela|muelas|paleta|colmillo|empaste|corona|funda|bracket|brackets|implante)\b/,
  /\b(golpe|golpes|golpeado|golpeada|accidente|caida|traumatismo)\b.*\b(boca|diente|dientes|muela|muelas|labio|labios|mandibula|paleta|encia|encias)\b/,
  /\b(boca|diente|dientes|muela|muelas|labio|labios|mandibula|paleta|encia|encias)\b.*\b(golpe|golpes|golpeado|golpeada|accidente|caida)\b/,
  /\btraumatismo\b/,
  // Espanol: embarazo, enfermedades y medicacion
  /\bembarazada\b/, /\bembarazo\b/, /\blactancia\b/, /\bdando el pecho\b/,
  /\balergi(a|as|co|ca|cos|cas)\b/, /\bdiabet(es|ico|ica)\b/, /\bhipertens(o|a|ion)\b/,
  /\bcardiac[oa]s?\b/, /\bmarcapasos\b/, /\banticoagula(nte|ntes|do|da|cion)\b/, /\bsintrom\b/,
  /\bmedicaci(on|ones)\b/, /\bmedicamentos?\b/, /\bantibiotic[oa]s?\b/,
  /\b(ibuprofeno|paracetamol|nolotil|enantyum|amoxicilina|augmentine|metamizol|dexketoprofeno)\b/,
  /\b(tomo|tomando|tomar|tome)\s+(pastillas?|medicacion|medicamentos?|antibioticos?|algo para el dolor)\b/,
  /\b(recetame|recetar|recetarme|me recetes|me recete)\b/,
  // Combinaciones de parte de la boca + sintoma
  /\b(caries|encia|encias|muelas?|dientes?|mandibula|bruxismo)\b.*\b(dolor|duele|sangra|hinchad[oa]|roto|rota|pus|infeccion)\b/,
  /\b(dolor|duele|sangra|hinchad[oa]|roto|rota|pus|infeccion)\b.*\b(caries|encia|encias|muelas?|dientes?|mandibula|bruxismo)\b/,
  // Ingles
  /\btoothache\b/, /\b(tooth|teeth|gum|gums|jaw|mouth)\s+(pain|hurts?|aches?|bleeding|bleeds|swollen)\b/,
  /\bin pain\b/, /\bpainful\b/, /\bhurts\b/, /\bhurting\b/, /\bbleed(ing|s)?\b/, /\bswollen\b/,
  /\bswelling\b/, /\binfect(ion|ed)\b/, /\babscess\b/, /\bfever\b/,
  /\b(broken|chipped|cracked)\s+(tooth|teeth|filling|crown)\b/, /\bpregnan(t|cy)\b/,
  /\ballerg(y|ic|ies)\b/, /\bmedication\b/, /\bantibiotics?\b/,
  // Portugues
  /\bdor(es)? de dentes?\b/, /\b(tenho|estou com|sinto|com|muita|muitas)\s+dor(es)?\b/, /\bdoendo\b/,
  /\b(dente|dentes|gengiva|boca|queixo)\b.*\bdoi\b/, /\bdoi\b.*\b(dente|dentes|gengiva|boca)\b/,
  /\bsangramento\b/, /\binchad[oa]s?\b/, /\binfec(c)?ao\b/, /\bfebre\b/, /\babscesso\b/, /\bgravida\b/,
  // Frances
  /\bdouleurs?\b/, /\bmal (aux dents|a la dent|a une dent)\b/, /\bj'?ai mal\b/, /\bsaigne(ment)?\b/,
  /\bgonfle(e|es|s)?\b/, /\bfievre\b/, /\babces\b/, /\benceinte\b/, /\ballergi(e|que)\b/,
  /\bmedicaments?\b/, /\bantibiotiques?\b/
];

const contieneInfoClinicaPrivada = texto => {
  const raw = (texto || '').toString();
  if (!raw.trim()) return false;
  // "Dolores" es un nombre y tambien el plural de "dolor". Se trata como nombre
  // cuando va tras "me llamo / soy / a nombre de...", cuando le sigue un
  // apellido con mayuscula o cuando aparece con mayuscula en mitad de frase.
  const sinNombres = raw
    .replace(/\b(me llamo|mi nombre es|a nombre de|de parte de|soy|nombre\s*[:=])\s+((?:mar[ií]a|mari)\s+)?dolores\b/gi, '$1 NOMBRE')
    .replace(/\b(?:mar[ií]a|mari)\s+dolores\b/gi, 'NOMBRE')
    .replace(/\bDolores(?=\s+[A-ZÁÉÍÓÚÑ])/g, 'NOMBRE')
    .replace(/([^\s.!?¿¡]\s+)Dolores\b/g, '$1NOMBRE');
  const valor = normalizarTexto(sinNombres);
  if (!valor) return false;
  return PATRONES_CLINICOS.some(patron => patron.test(valor));
};

// BAJA Y ALTA DE MENSAJES (opt-out). Frases deliberadamente concretas: "baja"
// o "stop" solo cuentan si son el mensaje entero, para que "tengo la baja
// medica y no puedo ir" no dé de baja a nadie.
const limpiarParaComando = texto => normalizarTexto(texto).replace(/[.,;:!¡?¿"'()]+/g, ' ').replace(/\s+/g, ' ').trim();
const esBajaMensajes = texto => {
  const valor = limpiarParaComando(texto);
  if (!valor) return false;
  if (/^(stop|baja|parar|para ya|unsubscribe|darme de baja|dame de baja|de baja|no me escribas|no me escribais|no me escriban)$/.test(valor)) return true;
  return /\b(no me (escribas|escribais|escriban|mandes|mandeis|manden|envies|envieis|envien) (mas|nada|mensajes|recordatorios|whatsapps?)|no (quiero|deseo) recibir (mas )?(mensajes|recordatorios|avisos|whatsapps?)|no quiero (mas|que me escribais|que me escribas|que me escriban)|dejad de escribirme|deja de escribirme|dejen de escribirme|dejad de mandarme|deja de mandarme|quiero darme de baja|darme de baja de|dame de baja|dadme de baja|stop mensajes)\b/.test(valor);
};
const esSolicitudSupresionDatos = texto => {
  const valor = limpiarParaComando(texto);
  if (!valor) return false;
  return /\b(borr(a|ad|en|ar|eis)|elimin(a|ad|en|ar|eis)|suprim(e|id|an|ir))\s+(todos\s+)?(mis|los)\s+datos\b|\bderecho (de|al) (supresion|olvido|acceso)\b|\bque datos (teneis|tienen|tienes) (de mi|mios|sobre mi)\b/.test(valor);
};
const esAltaMensajes = texto => {
  const valor = limpiarParaComando(texto);
  return /^(alta|darme de alta|dame de alta|volver a recibir (mensajes|recordatorios)|quiero (volver a )?recibir (los )?recordatorios)$/.test(valor);
};


const datosDerivacionHumano = (data = {}, opciones = {}) => {
  const nombreCandidato = data.nombre || data.paciente || extraerNombreMensaje(mensajeActual) || '';
  const nombre = !datoVacio(nombreCandidato) && !nombrePareceEjemploPrompt(nombreCandidato)
    ? limitarTexto(nombreCandidato, 120)
    : '';
  const motivo = limitarTexto(opciones.motivo || data.motivo || data.motivo_derivacion || 'consulta clinica privada', 180);
  const resumen = limitarTexto(
    opciones.resumen || data.resumen || data.resumen_derivacion || data.comentario || mensajeActual || 'El paciente solicita atencion humana.',
    900
  );
  const derivacionId = data.derivacion_id || ('DH-' + [telefono || 'sin-telefono', Date.now().toString(36)]
    .join('-')
    .replace(/[^a-z0-9-]/gi, '')
    .slice(0, 90));
  const derivadoEn = data.derivado_en || new Intl.DateTimeFormat('es-ES', {
    timeZone: TIME_ZONE,
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  }).format(new Date()).replace(',', '');
  // Texto de Legal/06, apartado 2. Las dos advertencias son obligatorias: "no
  // puedo darte consejo medico" y el 112. Sin ellas un paciente puede entender
  // que el bot le ha valorado y quedarse en casa.
  const telUrgencias = CFG.telefono_publico ? CFG.telefono_publico + ' o al 112' : '112';
  const respuestaDerivacion = opciones.respuesta || [
    'Gracias por contarme lo que te pasa. Le paso el mensaje al equipo de la clínica para que te llamen lo antes posible.',
    '',
    '⚠️ No puedo darte consejo médico ni valorar tu caso: para eso hace falta un profesional.',
    '',
    'Si es urgente y te encuentras mal, llama al ' + telUrgencias + '.'
  ].join('\n');
  // Codigo secreto del boton "Marcar como atendida" de los emails (workflow 07).
  const tokenCierre = (() => {
    try {
      if (globalThis.crypto && typeof globalThis.crypto.randomUUID === 'function') {
        return globalThis.crypto.randomUUID().replace(/-/g, '') + globalThis.crypto.randomUUID().replace(/-/g, '').slice(0, 8);
      }
    } catch (e) {}
    return Array.from({ length: 5 }, () => Math.random().toString(36).slice(2, 10)).join('');
  })();

  return {
    es_derivacion_humano: true,
    requiere_derivacion_humano: true,
    derivacion_id: derivacionId,
    derivado_en: derivadoEn,
    nombre,
    motivo_derivacion: motivo,
    resumen_derivacion: resumen,
    mensaje_original: limitarTexto(mensajeActual, 1200),
    respuesta_derivacion: respuestaDerivacion,
    token_cierre: tokenCierre
  };
};

const crearDerivacionHumano = (data = {}, opciones = {}) => {
  const derivacion = datosDerivacionHumano(data, opciones);
  return [{
    json: {
      accion: 'derivar_humano',
      es_reserva: false,
      es_cancelacion: false,
      es_modificacion: false,
      telefono,
      ...derivacion,
      ...(opciones.extra || {}),
      respuesta: derivacion.respuesta_derivacion
    }
  }];
};

if (!output) {
  if (contieneInfoClinicaPrivada(mensajeActual)) {
    return crearDerivacionHumano({});
  }
  if (preguntaIdentidad(mensajeActualNormalizado)) {
    return responder('Por privacidad no puedo identificarte solo por el chat. Si quieres gestionar una cita, dime tu nombre completo y te ayudo encantada.');
  }
  if (esSaludoSimple(mensajeActualNormalizado)) {
    return responder('Hola, soy ' + CFG.nombre_asistente + ' de ' + CFG.nombre + '. En que puedo ayudarte?');
  }
  if (/\b(cita|reservar|reserva|agendar|pedir hora|appointment|marcar consulta)\b/.test(mensajeActualNormalizado)) {
    return responder('Claro. Me dices tu nombre completo para empezar con la reserva?');
  }
}

const normHora = h => {
  if (h === null || h === undefined || h === '') return '';
  if (typeof h === 'number') {
    let totalMin;
    if (h >= 0 && h < 1) {
      totalMin = Math.round(h * 24 * 60);
    } else {
      const horas = Math.floor(h);
      const minutos = Math.round((h - horas) * 60);
      totalMin = horas * 60 + minutos;
    }
    const hh = Math.floor(totalMin / 60).toString().padStart(2, '0');
    const mm = (totalMin % 60).toString().padStart(2, '0');
    return hh + ':' + mm;
  }

  let v = h.toString().trim().toLowerCase();
  v = v.replace(/\s*(horas|hora|hrs?|h)\s*$/i, '').trim();
  v = v.replace('.', ':');

  const ampm = v.match(/^(\d{1,2})(?::(\d{1,2}))?\s*(am|pm)$/i);
  if (ampm) {
    let hh = parseInt(ampm[1], 10);
    const mm = (ampm[2] || '0').padStart(2, '0');
    if (ampm[3].toLowerCase() === 'pm' && hh < 12) hh += 12;
    if (ampm[3].toLowerCase() === 'am' && hh === 12) hh = 0;
    return hh.toString().padStart(2, '0') + ':' + mm;
  }

  if (/^\d{1,2}$/.test(v)) {
    let hh = parseInt(v, 10);
    if (hh >= 1 && hh <= 8) hh += 12;
    return hh.toString().padStart(2, '0') + ':00';
  }
  if (/^\d{1,2}:\d{1,2}:\d{1,2}$/.test(v)) v = v.split(':').slice(0, 2).join(':');
  if (/^\d{1,2}:\d{1,2}$/.test(v)) {
    const parts = v.split(':');
    return parts[0].padStart(2, '0') + ':' + parts[1].padStart(2, '0');
  }

  return v;
};

const horaEnMinutos = horaStr => {
  const m = (horaStr || '').match(/^(\d{2}):(\d{2})$/);
  if (!m) return null;
  const hh = parseInt(m[1], 10);
  const mm = parseInt(m[2], 10);
  if (hh < 0 || hh > 23 || mm < 0 || mm > 59) return null;
  return hh * 60 + mm;
};

const sumarMinutos = (horaStr, minutos) => {
  const inicio = horaEnMinutos(horaStr);
  if (inicio === null) return '';
  const total = inicio + minutos;
  const hh = Math.floor(total / 60).toString().padStart(2, '0');
  const mm = (total % 60).toString().padStart(2, '0');
  return hh + ':' + mm;
};

const fechaISOValida = fechaStr => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(fechaStr || '')) return false;
  const parts = fechaStr.split('-').map(Number);
  const d = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2]));
  return d.getUTCFullYear() === parts[0] && d.getUTCMonth() === parts[1] - 1 && d.getUTCDate() === parts[2];
};

const obtenerDiaSemana = fechaStr => {
  if (!fechaISOValida(fechaStr)) return -1;
  const parts = fechaStr.split('-').map(Number);
  return new Date(Date.UTC(parts[0], parts[1] - 1, parts[2])).getUTCDay();
};

const hoyClinica = () => {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(new Date());
  const get = type => parts.find(p => p.type === type).value;
  return get('year') + '-' + get('month') + '-' + get('day');
};

const fechaClinicaMasDias = dias => {
  const base = hoyClinica().split('-').map(Number);
  const d = new Date(Date.UTC(base[0], base[1] - 1, base[2] + dias));
  return d.getUTCFullYear() + '-' + (d.getUTCMonth() + 1).toString().padStart(2, '0') + '-' + d.getUTCDate().toString().padStart(2, '0');
};

const normalizarFechaEntrada = valor => {
  const raw = (valor || '').toString().trim();
  if (!raw) return '';
  const texto = normalizarTexto(raw);

  if (/\b(pasado manana|pasado ma?ana|after tomorrow|depois de amanha|depois de amanh?)\b/.test(texto)) {
    return fechaClinicaMasDias(2);
  }
  if (/\b(manana|ma?ana|tomorrow|amanha|amanh?)\b/.test(texto)) {
    return fechaClinicaMasDias(1);
  }
  if (/\b(hoy|today|hoje)\b/.test(texto)) {
    return hoyClinica();
  }

  const iso = raw.match(/(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})/);
  if (iso) {
    const fecha = iso[1] + '-' + iso[2].padStart(2, '0') + '-' + iso[3].padStart(2, '0');
    return fechaISOValida(fecha) ? fecha : '';
  }

  const europeo = raw.match(/(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})/);
  if (europeo) {
    const fecha = europeo[3] + '-' + europeo[2].padStart(2, '0') + '-' + europeo[1].padStart(2, '0');
    return fechaISOValida(fecha) ? fecha : '';
  }

  const meses = {
    january: 1, jan: 1, enero: 1, janeiro: 1, janvier: 1,
    february: 2, feb: 2, febrero: 2, fevereiro: 2, fevrier: 2, fevrier: 2,
    march: 3, mar: 3, marzo: 3, marco: 3, mars: 3,
    april: 4, apr: 4, abril: 4, avril: 4,
    may: 5, mayo: 5, maio: 5, mai: 5,
    june: 6, jun: 6, junio: 6, junho: 6, juin: 6,
    july: 7, jul: 7, julio: 7, julho: 7, juillet: 7,
    august: 8, aug: 8, agosto: 8, aout: 8,
    september: 9, sep: 9, septiembre: 9, setembro: 9, septembre: 9,
    october: 10, oct: 10, octubre: 10, outubro: 10, octobre: 10,
    november: 11, nov: 11, noviembre: 11, novembro: 11, novembre: 11,
    december: 12, dec: 12, diciembre: 12, dezembro: 12, decembre: 12
  };
  const monthName = Object.keys(meses).find(mes => new RegExp('\\b' + mes + '\\b').test(texto));
  if (monthName) {
    const yearMatch = raw.match(/(20\d{2})/);
    const sinYear = raw.replace(/20\d{2}/g, ' ');
    const dayMatches = [...sinYear.matchAll(/\b(\d{1,2})\b/g)].map(match => Number(match[1])).filter(n => n >= 1 && n <= 31);
    const day = dayMatches[dayMatches.length - 1];
    const year = yearMatch ? Number(yearMatch[1]) : Number(hoyClinica().slice(0, 4));
    if (day) {
      const fecha = year + '-' + meses[monthName].toString().padStart(2, '0') + '-' + day.toString().padStart(2, '0');
      return fechaISOValida(fecha) ? fecha : '';
    }
  }

  return '';
};

const normalizarFechasAccion = (data, accion) => {
  for (const campo of ['fecha', 'fecha_actual', 'fecha_nueva']) {
    const fecha = normalizarFechaEntrada(data[campo]);
    if (fecha) data[campo] = fecha;
  }

  const fechaMensaje = normalizarFechaEntrada(mensajeActual);
  if (fechaMensaje) {
    if ((accion === 'reservar' || accion === 'consultar_horarios' || accion === 'cancelar') && datoVacio(data.fecha)) {
      data.fecha = fechaMensaje;
    }
    if (accion === 'modificar' && datoVacio(data.fecha_nueva)) {
      data.fecha_nueva = fechaMensaje;
    }
  }
};

const validarFechaFutura = fechaStr => fechaISOValida(fechaStr) && fechaStr >= hoyClinica();

const horarioDia = fechaStr => {
  const dia = obtenerDiaSemana(fechaStr);
  if (dia === -1) return null;
  return CFG.horarios[dia] || null;
};

const validarHorario = (fechaStr, horaStr, duracionMin = DURACION_CITA_MIN) => {
  const horario = horarioDia(fechaStr);
  const inicio = horaEnMinutos(horaStr);
  if (!horario || inicio === null) return false;
  const apertura = horaEnMinutos(horario.apertura);
  const cierre = horaEnMinutos(horario.cierre);
  if (apertura === null || cierre === null) return false;
  return inicio >= apertura && inicio + duracionMin <= cierre;
};

// Una cita solo cabe si TERMINA antes de cerrar. Con cierre a las 20:00 y una
// limpieza de 45 min, la ultima hora a la que se puede empezar es 19:15.
const ultimaHoraInicio = (fechaStr, duracionMin) => {
  const horario = horarioDia(fechaStr);
  if (!horario) return '';
  const apertura = horaEnMinutos(horario.apertura);
  const cierre = horaEnMinutos(horario.cierre);
  if (apertura === null || cierre === null) return '';
  const ultima = cierre - duracionMin;
  if (ultima < apertura) return '';
  return Math.floor(ultima / 60).toString().padStart(2, '0') + ':' + (ultima % 60).toString().padStart(2, '0');
};

// Explica POR QUE no cabe, en vez de soltar el horario y dejar al paciente
// pensando que las 20:00 valen porque "abrimos hasta las 20:00".
const mensajeFueraDeHorario = (fechaStr, duracionMin) => {
  const horario = horarioDia(fechaStr);
  if (!horario) {
    return 'Ese día la clínica está cerrada. Nuestro horario es: ' + CFG.horarioTexto + '. ¿Te viene bien otro día?';
  }
  const ultima = ultimaHoraInicio(fechaStr, duracionMin);
  if (ultima) {
    return 'Esa hora no me cuadra: ese día atendemos de ' + horario.apertura + ' a ' + horario.cierre
      + ', y la cita dura ' + duracionMin + ' minutos, así que la última que puedo darte empieza a las '
      + ultima + '. ¿Te viene bien esa u otra antes?';
  }
  return 'Esa hora queda fuera de nuestro horario. Nuestro horario es: ' + CFG.horarioTexto + '. ¿Qué otra hora te vendría bien?';
};

const offsetClinica = (fechaStr, horaStr) => {
  const probe = new Date(fechaStr + 'T' + horaStr + ':00Z');
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TIME_ZONE,
    hour: '2-digit',
    minute: '2-digit',
    timeZoneName: 'longOffset'
  }).formatToParts(probe);
  const tz = (parts.find(p => p.type === 'timeZoneName') || {}).value || 'GMT+00:00';
  const m = tz.match(/GMT([+-])(\d{1,2})(?::?(\d{2}))?/);
  if (!m) return '+00:00';
  return m[1] + m[2].padStart(2, '0') + ':' + (m[3] || '00').padStart(2, '0');
};

const isoClinica = (fechaStr, horaStr) => fechaStr + 'T' + horaStr + ':00' + offsetClinica(fechaStr, horaStr);

const fechaHoraFutura = (fechaStr, horaStr) => {
  if (!fechaISOValida(fechaStr) || horaEnMinutos(horaStr) === null) return false;
  const fechaHora = new Date(isoClinica(fechaStr, horaStr));
  return !Number.isNaN(fechaHora.getTime()) && fechaHora.getTime() > Date.now();
};

const extraerTratamientoMensaje = texto => {
  const valor = normalizarTexto(texto);
  const encontrado = DURACIONES_TRATAMIENTO.find(item =>
    item.patrones.some(patron => valor.includes(normalizarTexto(patron)))
  );
  return encontrado ? encontrado.nombre : '';
};

const extraerHoraMensaje = texto => {
  const raw = (texto || '').toString().replace(/\s+/g, ' ').trim();
  const patrones = [
    /\b(?:a\s+)?(?:las?|los)\s+(\d{1,2})(?::(\d{1,2}))?\s*(am|pm)?\b/i,
    /\b(\d{1,2}):(\d{1,2})\s*(am|pm)?\b/i
  ];
  for (const patron of patrones) {
    const match = raw.match(patron);
    if (!match) continue;
    const valor = match[1] + (match[2] ? ':' + match[2] : '') + (match[3] ? ' ' + match[3] : '');
    const hora = normHora(valor);
    if (horaEnMinutos(hora) !== null) return hora;
  }
  return '';
};

const esSolicitudReservaAdministrativa = texto => /\b(cita|reservar|reserva|agendar|pedir hora|quiero|quisiera|necesito|appointment|marcar consulta)\b/.test(normalizarTexto(texto));

const esConsultaCitaExistente = texto => {
  const valor = normalizarTexto(texto);
  if (!valor || contieneInfoClinicaPrivada(texto)) return false;
  if (/\b(cancelar|cambiar|modificar|mover|reprogramar|reservar|agendar|pedir hora|horarios?|disponibilidad|huecos?|agenda)\b/.test(valor)) return false;
  const mencionaCita = /\b(mi cita|mis citas|mi reserva|mis reservas|cita que tengo|cita pendiente|cita reservada|cuando tengo cita|cuando tenia cita|cuando era mi cita|cuando es mi cita|cuando toca|cuando me toca|appointment|my appointment)\b/.test(valor)
    || (/\bcita\b/.test(valor) && /\b(cuando|fecha|hora|dia|recordar|recuerdame|saber|consultar|confirmar|ver|buscar|tengo|tenia)\b/.test(valor));
  const mencionaTratamientoYaReservado = contieneTratamiento(valor)
    && /\b(tenia|tengo|reserve|reservado|reservada|no se cuando|no recuerdo|cuando fue|cuando era|cuando es)\b/.test(valor);
  return mencionaCita || mencionaTratamientoYaReservado;
};

const EXTRAS_COMERCIALES = ['implante', 'implantes', 'carillas', 'invisalign'];
const contieneServicioComercialLead = texto => {
  const valor = normalizarTexto(texto);
  return DURACIONES_TRATAMIENTO.some(item => item.patrones.some(p => valor.includes(normalizarTexto(p))))
    || EXTRAS_COMERCIALES.some(p => valor.includes(p));
};

const esConsultaComercialLead = texto => {
  const valor = normalizarTexto(texto);
  if (!valor || contieneInfoClinicaPrivada(texto) || esConsultaCitaExistente(texto)) return false;
  if (/\b(cancelar|cambiar|modificar|mover|reprogramar|reservar|reserva|cita|agendar|pedir hora|horarios?|disponibilidad|huecos?|agenda)\b/.test(valor)) return false;
  if (/\b(servicios?|que ofrecen|que tratamientos tienen|que servicios tienen|direccion|telefono|horario)\b/.test(valor) && !contieneServicioComercialLead(valor)) return false;
  return contieneServicioComercialLead(valor)
    && /\b(precio|precios|cuanto cuesta|coste|costos|presupuesto|financiacion|financiado|informacion|info|me interesa|interesado|interesada|quiero saber|llamadme|llamarme|contactarme|consulta comercial|ortodoncia|blanqueamiento|limpieza|empaste|revision|implante|implantes|carillas|invisalign)\b/.test(valor);
};

const esConsultaServiciosGeneral = texto => {
  const valor = normalizarTexto(texto);
  if (!valor || contieneInfoClinicaPrivada(texto)) return false;
  if (/\b(precio|precios|cuanto cuesta|coste|costos|presupuesto|financiacion|financiado|reservar|reserva|cita|agendar|pedir hora|horarios?|disponibilidad|huecos?|agenda)\b/.test(valor)) return false;
  return /\b(servicios?|tratamientos?|que ofrecen|que servicios tienen|que tratamientos tienen)\b/.test(valor);
};

const esRechazoSeguimientoLead = texto => {
  const valor = normalizarTexto(texto);
  if (!valor || contieneInfoClinicaPrivada(texto)) return false;
  return /\b(no quiero nada|no me interesa|no estoy interesado|no estoy interesada|ya no me interesa|no gracias|gracias pero no|dejalo|dejalo asi|no contactar|no contactarme)\b/.test(valor);
};

const interesLeadInvalido = valor => {
  const texto = normalizarTexto(valor);
  return !texto
    || ['x', 'ninguno', 'ninguna', 'none', 'null', 'no', 'no especificado', 'sin especificar', 'desconocido', 'servicios', 'servicios generales', 'informacion general', 'info general', 'consulta comercial', 'cita estandar'].includes(texto)
    || texto.includes('ningun')
    || texto.includes('no quiero')
    || texto.includes('no gracias');
};

const interesLeadValido = data => {
  const interes = data.tratamiento_interes || data.tratamiento || data.interes || data.servicio || '';
  if (interesLeadInvalido(interes)) return false;
  return contieneServicioComercialLead(interes) || contieneServicioComercialLead(mensajeActual);
};

const crearConsultaCita = (data = {}) => {
  const nombreCandidato = data.nombre || data.paciente || extraerNombreMensaje(mensajeActual) || '';
  const nombre = !datoVacio(nombreCandidato) && !nombrePareceEjemploPrompt(nombreCandidato)
    ? limitarTexto(nombreCandidato, 120)
    : '';
  const tratamientoCandidato = data.tratamiento || data.tratamiento_interes || data.servicio || extraerTratamientoMensaje(mensajeActual) || '';
  const tratamiento = !tratamientoPareceEjemploPrompt(tratamientoCandidato)
    ? limitarTexto(tratamientoCandidato, 180)
    : '';

  return [{
    json: {
      accion: 'consultar_cita',
      es_reserva: false,
      es_cancelacion: false,
      es_modificacion: false,
      es_consulta_cita: true,
      telefono,
      ...(nombre ? { nombre } : {}),
      ...(tratamiento ? { tratamiento } : {})
    }
  }];
};

const crearLead = (data = {}, respuestaFallback = '') => {
  const nombreCandidato = data.nombre || data.paciente || extraerNombreMensaje(mensajeActual) || '';
  const nombre = !datoVacio(nombreCandidato) && !nombrePareceEjemploPrompt(nombreCandidato)
    ? limitarTexto(nombreCandidato, 120)
    : '';
  const tratamiento = limitarTexto(
    data.tratamiento_interes || data.tratamiento || data.interes || data.servicio || extraerTratamientoMensaje(mensajeActual) || 'Consulta comercial',
    180
  );
  const resumen = limitarTexto(data.resumen_lead || data.resumen || data.motivo || mensajeActual || 'Interes comercial recibido por WhatsApp.', 900);
  const respuesta = limitarTexto(
    data.respuesta || respuestaFallback || 'Gracias, lo dejo anotado. Si quieres, puedo ayudarte a ver horarios para una cita o pasar tu consulta a la clinica.',
    900
  );

  return [{
    json: {
      accion: 'registrar_lead',
      es_reserva: false,
      es_cancelacion: false,
      es_modificacion: false,
      es_lead: true,
      telefono,
      nombre,
      tratamiento_interes: tratamiento,
      resumen_lead: resumen,
      mensaje_original: limitarTexto(mensajeActual, 1200),
      respuesta
    }
  }];
};

const completarReservaDesdeMensaje = (data = {}) => {
  if (!esSolicitudReservaAdministrativa(mensajeActual)) return null;
  const reserva = { ...data };
  const nombre = extraerNombreMensaje(mensajeActual);
  if ((datoVacio(reserva.nombre) || nombrePareceEjemploPrompt(reserva.nombre)) && nombre) {
    reserva.nombre = nombre;
  }
  if (datoVacio(reserva.tratamiento) || tratamientoGenerico(reserva.tratamiento) || tratamientoPareceEjemploPrompt(reserva.tratamiento)) {
    const tratamiento = extraerTratamientoMensaje(mensajeActual);
    if (tratamiento) reserva.tratamiento = tratamiento;
  }
  if (datoVacio(reserva.fecha)) {
    const fecha = normalizarFechaEntrada(mensajeActual);
    if (fecha) reserva.fecha = fecha;
  }
  if (datoVacio(reserva.hora)) {
    const hora = extraerHoraMensaje(mensajeActual);
    if (hora) reserva.hora = hora;
  }

  const nombreValido = !datoVacio(reserva.nombre) && !nombrePareceEjemploPrompt(reserva.nombre);
  const tratamientoValido = !datoVacio(reserva.tratamiento) && !tratamientoPareceEjemploPrompt(reserva.tratamiento);
  const fechaValida = !datoVacio(reserva.fecha);
  const horaValida = !datoVacio(reserva.hora);
  if (!nombreValido || !tratamientoValido || !fechaValida || !horaValida) return null;
  return { ...reserva, accion: 'reservar' };
};

