          ...derivacionAdjunta
        }
      }];
    }

    if (accion === 'cancelar') {
      if (!datoVacio(data.nombre) && nombrePareceEjemploPrompt(data.nombre)) {
        return responder('Claro. Me dices el nombre completo de la cita?');
      }
      if (datoVacio(data.nombre)) {
        return responder('Claro. ¿Me dices el nombre completo de la cita?');
      }
      if (datoVacio(data.fecha)) {
        return responder('¿Qué fecha tiene la cita que quieres cancelar?');
      }
      if (datoVacio(data.hora)) {
        return responder('¿A qué hora era la cita?');
      }
      const hora = normHora(data.hora);
      if (!fechaISOValida(data.fecha) || horaEnMinutos(hora) === null) {
        return responder('Necesito la fecha en formato YYYY-MM-DD y la hora en formato HH:mm para localizar la cita.');
      }
      return [{
        json: {
          accion: 'cancelar',
          es_reserva: false,
          es_cancelacion: true,
