      if (!fechaHoraFutura(data.fecha_nueva, horaNueva)) {
        return responder('Esa nueva hora ya ha pasado. ¿Me dices otra hora futura que te venga bien?');
      }
      if (!validarHorario(data.fecha_nueva, horaNueva, duracion)) {
        return responder(mensajeFueraDeHorario(data.fecha_nueva, duracion));
      }
      const horaFinNueva = sumarMinutos(horaNueva, duracion);
