const normalizarTexto = texto => (texto || '')
  .toString()
  .toLowerCase()
  .normalize('NFD')
  .replace(/[̀-ͯ]/g, '')
  .replace(/\s+/g, ' ')
  .trim();
const normalizarTelefono = v => (v || '').toString().replace(/\D/g, '');
const telefonosCompatibles = (a, b) => {
  const x = normalizarTelefono(a);
  const y = normalizarTelefono(b);
  if (!x || !y) return false;
  return x === y || (x.length >= 9 && y.length >= 9 && x.slice(-9) === y.slice(-9));
};
const normFecha = f => {
  const m = (f || '').toString().trim().match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? m[1] + '-' + m[2] + '-' + m[3] : '';
};
const normHora = h => {
  const m = (h || '').toString().trim().match(/^(\d{1,2}):(\d{2})/);
  return m ? m[1].padStart(2, '0') + ':' + m[2] : (h || '').toString();
};
