    && telefonosCompatibles(row.telefono, telefono))
  .sort((a, b) => (normFecha(a.fecha) + normHora(a.hora)).localeCompare(normFecha(b.fecha) + normHora(b.hora)));

const mismoDia = citasDelTelefono.find(row => normFecha(row.fecha) === reserva.fecha
