const pasoMinutos = 30;

const horaEnMinutos = horaStr => {
  const m = (horaStr || '').match(/^(\d{2}):(\d{2})$/);
  if (!m) return null;
  return parseInt(m[1], 10) * 60 + parseInt(m[2], 10);
};

const formatoHora = minutos => {
  const hh = Math.floor(minutos / 60).toString().padStart(2, '0');
  const mm = (minutos % 60).toString().padStart(2, '0');
  return hh + ':' + mm;
};

const hoyClinica = () => {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(new Date());
  const get = type => parts.find(p => p.type === type).value;
  return get('year') + '-' + get('month') + '-' + get('day');
};

const offsetClinica = (fechaStr, horaStr) => {
  const probe = new Date(fechaStr + 'T' + horaStr + ':00Z');
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TIME_ZONE,
    hour: '2-digit',
    minute: '2-digit',
    timeZoneName: 'longOffset'
  }).formatToParts(probe);
  const tz = (parts.find(p => p.type === 'timeZoneName') || {}).value || 'GMT+00:00';
  const m = tz.match(/GMT([+-])(\d{1,2})(?::?(\d{2}))?/);
  if (!m) return '+00:00';
  return m[1] + m[2].padStart(2, '0') + ':' + (m[3] || '00').padStart(2, '0');
};

const isoClinica = (fechaStr, horaStr) => fechaStr + 'T' + horaStr + ':00' + offsetClinica(fechaStr, horaStr);

