  const horaInicio = formatoHora(inicioMin);
  const horaFin = formatoHora(inicioMin + duracion);
  const slotInicio = new Date(isoClinica(fecha, horaInicio));
  const slotFin = new Date(isoClinica(fecha, horaFin));
  if (fecha === hoyClinica() && slotInicio <= ahora) continue;
  const ocupado = eventos.some(evento => slotInicio < evento.end && slotFin > evento.start);
