    for (let i = 0; i < horas.length; i += 4) {
      grupos.push(horas.slice(i, i + 4).join(', '));
    }
    return grupos.join('\n');
  };
  const manana = libres.filter(hora => hora < '14:00');
  const tarde = libres.filter(hora => hora >= '14:00');
